/* G2 persistence kernel: writes X9 many times with a known pattern after
   the injection point. If stuck_at_one bit b is armed on X9's phys reg,
   every write's bit b must come out as 1. We print whether the stuck bit
   (bit 0..7 for mask 0xff) ever read as 0 during the write-storm — that
   would prove the stuck fault did NOT persist (a G2 failure).
   Prints "STUCK_PERSIST_OK" or "STUCK_LOST" + a sample value. */
#include <unistd.h>
#include <stdint.h>

static void put(const char *s){ while(*s) { write(2,s,1); s++; } }
static void put_hex(unsigned long v){ char b[16]; for(int i=15;i>=0;--i){unsigned d=v&0xf;b[i]=d<10?'0'+d:'a'+d-10;v>>=4;} write(2,b,16); write(2,"\n",1);}

int main(void){
    volatile unsigned long x = 0;
    /* ROI: a write storm on the accumulator. The injector targets the
       phys reg backing this accumulator around cycle 100000. */
    for (volatile unsigned long i=0;i<5000000UL;++i){
        x = i;              /* write a value whose low bits vary 0..255 */
        x ^= 0xdeadbeef;
    }
    /* After the storm: read back. If a stuck_at_one bit was armed, that
       bit must read 1 regardless of the last written value. */
    put("FINAL="); put_hex(x); put("\n");
    return 0;
}
EOF
